const item = $input.first().json;
const stop = new Set(['i','a','o','w','z','do','na','dla','jako','oraz','aby','żeby','swojej','swoje','swoich','to','jest','są','być','the','and','for','with','to','of','in','on','at','as','an','by','is','be','our','your']);
const text = `${item.goal} ${item.currentHeadline} ${item.currentAbout}`.toLowerCase();
const tokens = text.match(/[\p{L}][\p{L}0-9+#\.-]{2,}/gu) || [];
const freq = {};
for (const t of tokens) {
  if (stop.has(t)) continue;
  freq[t] = (freq[t] || 0) + 1;
}
const topKeywords = Object.entries(freq)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 14)
  .map(([w]) => w);

const aboutLen = (item.currentAbout || '').length;
const headlineLen = (item.currentHeadline || '').length;
const skillCount = (item.currentSkills || []).length;

return [{
  json: {
    ...item,
    extractedKeywords: topKeywords,
    auditBefore: {
      headlineLen,
      aboutLen,
      skillCount,
      headlineScore: Math.min(100, Math.round(headlineLen / 220 * 100)),
      aboutScore: aboutLen < 600 ? Math.round(aboutLen / 6) : (aboutLen > 2600 ? 80 : 100)
    }
  }
}];

