const aiItem = $input.first().json;
const input = $('⛏ Mine Keywords (free)').first().json;
const raw = aiItem.choices?.[0]?.message?.content || '';
let parsed = { newHeadline: '', newAbout: '', recommendedSkills: [], contentAngles: [], keywordsUsed: [] };
try { parsed = JSON.parse(raw); }
catch {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch {} }
}

const clean = (s, max) => String(s || '').replace(/\u200B|\u200C|\u200D|\uFEFF/g, '').replace(/\s+\n/g, '\n').trim().slice(0, max);
const arrCap = (a, max) => Array.isArray(a) ? a.map(x => String(x).trim()).filter(Boolean).slice(0, max) : [];

const newHeadline = clean(parsed.newHeadline, 220);
const newAbout = clean(parsed.newAbout, 2400);
const recommendedSkills = arrCap(parsed.recommendedSkills, 40);
const contentAngles = arrCap(parsed.contentAngles, 3);
const keywordsUsed = arrCap(parsed.keywordsUsed, 15);

// Audit AFTER
const lower = newAbout.toLowerCase();
const hits = keywordsUsed.filter(k => lower.includes(String(k).toLowerCase())).length;
const kwDensity = keywordsUsed.length > 0 ? Math.round(hits / keywordsUsed.length * 100) : 0;
const headlineScore = Math.min(100, Math.round(newHeadline.length / 220 * 100));
const aboutScore = newAbout.length < 600 ? Math.round(newAbout.length / 6) : (newAbout.length > 2400 ? 80 : 100);

const auditAfter = {
  headlineLen: newHeadline.length,
  aboutLen: newAbout.length,
  skillCount: recommendedSkills.length,
  headlineScore,
  aboutScore,
  keywordCoverage: kwDensity
};

const delta = {
  headlineLen: auditAfter.headlineLen - input.auditBefore.headlineLen,
  aboutLen: auditAfter.aboutLen - input.auditBefore.aboutLen,
  skillCount: auditAfter.skillCount - input.auditBefore.skillCount,
  headlineScore: auditAfter.headlineScore - input.auditBefore.headlineScore,
  aboutScore: auditAfter.aboutScore - input.auditBefore.aboutScore
};

return [{
  json: {
    newHeadline,
    newAbout,
    recommendedSkills,
    contentAngles,
    keywordsUsed,
    audit: { before: input.auditBefore, after: auditAfter, delta },
    usage: {
      promptTokens: aiItem.usage?.prompt_tokens || 0,
      completionTokens: aiItem.usage?.completion_tokens || 0
    }
  }
}];
